import{_ as a,C as s,o as r,c as d,E as o,a3 as i}from"./chunks/framework.CCylkYel.js";const n="/screens/devices/chance.png",l="/screens/devices/chance-pass.png",h="/screens/devices/chance-block.png",_=JSON.parse('{"title":"Chance","description":"","frontmatter":{"title":"Chance","pageClass":"device-doc"},"headers":[],"relativePath":"devices/chance.md","filePath":"devices/chance.md"}'),c={name:"devices/chance.md"};function g(p,t,m,u,y,b){const e=s("DeviceHeading");return r(),d("div",null,[o(e,{slug:"chance",title:"Chance"}),t[0]||(t[0]=i('<p>Probabilistic note gate</p><p><img src="'+n+'" alt="Chance parameters" class="screen"></p><p>The right side shows what Chance just did. One mark says the last decision: an arrow through the open gate means <strong>PASS</strong>, the same arrow stopped against a closed bar means <strong>BLOCK</strong>. Until the first note is decided there is only the dim outline of the gate.</p><p><img src="'+l+'" alt="Chance, a note passes" class="screen"></p><p><img src="'+h+'" alt="Chance, a note is blocked" class="screen"></p><p>With <strong>RATE</strong> set, a row of outline pips under the mark fills from left to right as the current period runs, then starts again. The mark above it is the decision held for that period. While the clock is stopped the pips rest dim at the start. With <strong>RATE</strong> off every note is decided on its own, so there is no timer row and the picture only shows the last decision.</p><h2 id="when-to-use-it" tabindex="-1">When to use it <a class="header-anchor" href="#when-to-use-it" aria-label="Permalink to &quot;When to use it&quot;">​</a></h2><p>Insert <strong>Chance</strong> to <strong>probabilistically pass or drop</strong> notes (and optionally scale surviving velocity). Use rate to thin a dense stream over time.</p><h2 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h2><div class="device-params-table"><table tabindex="0"><thead><tr><th>Parameter</th><th>Range</th><th>What it does</th></tr></thead><tbody><tr><td>BYPASS</td><td>0 – 1</td><td>When on, the device is disabled and MIDI passes through unchanged.</td></tr><tr><td>CHANCE</td><td>0 – 100</td><td>Probability (0–100%) that a note is allowed through.</td></tr><tr><td>RATE</td><td>0 – 7</td><td>Clock division for each step — how fast the pattern advances.</td></tr><tr><td>USE VELOCITY</td><td>0 – 1</td><td>When on, dropped notes scale remaining velocity instead of a hard mute.</td></tr></tbody></table></div><h2 id="parameter-values" tabindex="-1">Parameter values <a class="header-anchor" href="#parameter-values" aria-label="Permalink to &quot;Parameter values&quot;">​</a></h2><h3 id="bypass" tabindex="-1">Bypass <a class="header-anchor" href="#bypass" aria-label="Permalink to &quot;Bypass&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Value</th><th>Name</th><th>Meaning</th></tr></thead><tbody><tr><td style="text-align:right;">0</td><td>OFF</td><td>Device is active and processes MIDI.</td></tr><tr><td style="text-align:right;">1</td><td>ON</td><td>Device is bypassed; messages pass through unchanged.</td></tr></tbody></table><h3 id="rate" tabindex="-1">Rate <a class="header-anchor" href="#rate" aria-label="Permalink to &quot;Rate&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Value</th><th>Name</th><th>Meaning</th></tr></thead><tbody><tr><td style="text-align:right;">0</td><td>Off</td><td>No rate thinning — only per-note chance applies.</td></tr><tr><td style="text-align:right;">1</td><td>1/1</td><td>Allow roughly one message per 1/1 clock slice.</td></tr><tr><td style="text-align:right;">2</td><td>1/2</td><td>Allow roughly one message per 1/2 clock slice.</td></tr><tr><td style="text-align:right;">3</td><td>1/4</td><td>Allow roughly one message per 1/4 clock slice.</td></tr><tr><td style="text-align:right;">4</td><td>1/8</td><td>Allow roughly one message per 1/8 clock slice.</td></tr><tr><td style="text-align:right;">5</td><td>1/16</td><td>Allow roughly one message per 1/16 clock slice.</td></tr><tr><td style="text-align:right;">6</td><td>1/32</td><td>Allow roughly one message per 1/32 clock slice.</td></tr><tr><td style="text-align:right;">7</td><td>1/64</td><td>Allow roughly one message per 1/64 clock slice.</td></tr></tbody></table><h3 id="use-velocity" tabindex="-1">Use Velocity <a class="header-anchor" href="#use-velocity" aria-label="Permalink to &quot;Use Velocity&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Value</th><th>Name</th><th>Meaning</th></tr></thead><tbody><tr><td style="text-align:right;">0</td><td>OFF</td><td>Dropped notes are silent.</td></tr><tr><td style="text-align:right;">1</td><td>ON</td><td>Passed notes keep proportional velocity.</td></tr></tbody></table>',17))])}const f=a(c,[["render",g]]);export{_ as __pageData,f as default};
